import fs from 'fs';import path from 'path';const ROOT='sep18-final-cert-all',rows=[];function walk(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);if(e.isDirectory())walk(p);else if(e.name==='result.json'){try{rows.push(JSON.parse(fs.readFileSync(p,'utf8')))}catch{}}}}walk(ROOT);const valid=rows.filter(r=>r.http===200&&r.previewOk&&!r.error&&!r.brokenImages),invalid=rows.filter(r=>!(r.http===200&&r.previewOk&&!r.error&&!r.brokenImages));const avg=(g,k)=>{const a=valid.filter(x=>x.group===g);return a.length?Math.round(a.reduce((s,x)=>s+(x[k]||0),0)/a.length):0};const slow=[...valid].sort((a,b)=>(b.loadMs||0)-(a.loadMs||0));const out={generatedAt:new Date().toISOString(),counts:{total:rows.length,valid:valid.length,invalid:invalid.length,homepage:rows.filter(x=>x.group==='homepage').length,stateGuardRoot:rows.filter(x=>x.group==='state-guard-root').length},averages:{homepage:{loadMs:avg('homepage','loadMs'),fcpMs:avg('homepage','fcpMs'),lcpMs:avg('homepage','lcpMs')},stateGuardRoot:{loadMs:avg('state-guard-root','loadMs'),fcpMs:avg('state-guard-root','fcpMs'),lcpMs:avg('state-guard-root','lcpMs')}},over5s:valid.filter(x=>(x.loadMs||0)>5000).map(x=>({group:x.group,label:x.label,route:x.route,loadMs:x.loadMs,lcpMs:x.lcpMs,ttfbMs:x.ttfbMs})),slowest:slow.slice(0,20),invalid,rows};fs.mkdirSync('sep18-final-cert-summary',{recursive:true});fs.writeFileSync('sep18-final-cert-summary/summary.json',JSON.stringify(out,null,2));const md=['# Final Current-Draft Load Certification','',`Total ${out.counts.total}; valid ${out.counts.valid}; invalid ${out.counts.invalid}`,`Homepage ${out.counts.homepage}; State Guard root ${out.counts.stateGuardRoot}`,'',`Homepage avg load ${out.averages.homepage.loadMs} ms; avg LCP ${out.averages.homepage.lcpMs} ms`,`State Guard avg load ${out.averages.stateGuardRoot.loadMs} ms; avg LCP ${out.averages.stateGuardRoot.lcpMs} ms`,'','## Over 5 seconds',...(out.over5s.length?out.over5s.map(x=>`- ${x.group}: ${x.label} — ${x.loadMs} ms load; ${x.lcpMs} ms LCP; ${x.ttfbMs} ms TTFB`):['- None']),'','## Slowest 20',...out.slowest.map((r,i)=>`${i+1}. ${r.group}: ${r.label} — load ${r.loadMs} ms; LCP ${r.lcpMs} ms; TTFB ${r.ttfbMs} ms; ${Math.round((r.transferBytes||0)/1024)} KB; flags ${(r.flags||[]).join(', ')||'none'}`),'','## Invalid',...(invalid.length?invalid.map(r=>`- ${r.group}: ${r.label} — HTTP ${r.http}; preview=${r.previewOk}; error=${r.error||''}`):['- None'])];fs.writeFileSync('sep18-final-cert-summary/AUDIT.md',md.join('\n'));console.log('FINALCERT',JSON.stringify({counts:out.counts,averages:out.averages,over5s:out.over5s,slowest:out.slowest.slice(0,12).map(r=>({group:r.group,label:r.label,route:r.route,load:r.loadMs,lcp:r.lcpMs,ttfb:r.ttfbMs,kb:Math.round((r.transferBytes||0)/1024),flags:r.flags})),invalid:out.invalid}));if(invalid.length)process.exitCode=2;